import{_ as n,o as a,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const d=JSON.parse('{"title":"Объединение файлов KV с помощью #base","description":"","frontmatter":{"title":"Объединение файлов KV с помощью #base","author":"Perry","steamId":"76561198046986723","date":"06.04.2016"},"headers":[],"relativePath":"tools/combining-kv-files-using-base.md","filePath":"tools/combining-kv-files-using-base.md"}'),i={name:"tools/combining-kv-files-using-base.md"};function t(l,s,o,c,r,u){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="объединение-фаилов-kv-с-помощью-base" tabindex="-1">Объединение файлов KV с помощью #base <a class="header-anchor" href="#объединение-фаилов-kv-с-помощью-base" aria-label="Permalink to &quot;Объединение файлов KV с помощью #base&quot;">​</a></h1><p>Наличие одного kv-файла, содержащего определения каждого юнита или способности, как это установлено по умолчанию в интерфейсе мода, может очень быстро стать очень раздражающим. Разделение этого файла на несколько файлов KV меньшего размера упрощает обзор и управление файлами. Обычно для этого используют модкиты, но:</p><p><strong><a href="https://github.com/stephenfournier/Dota-2-ModKit" target="_blank" rel="noreferrer">ModKit</a> не требуется для объединения файлов KV</strong></p><p>Благодаря некоторой детективной работе, проделанной в #steamdb, и некоторому тестированию с моей стороны, мы обнаружили, что в dota KV есть рабочая директива #base, которая сообщает движку объединить другой файл KV с текущим.</p><p><strong>Этот метод работает для:</strong></p><ul><li>Файлы определения юнитов/способностей (например, <code>npc_units_custom.txt</code> или <code>npc_abilities_custom.txt</code>).</li><li>Пользовательские файлы значений ключей, загружаемые в lua с помощью LoadKeyValues.</li><li>Файлы локализации (<code>addon_english.txt</code>)</li></ul><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><p>Предположим, мы начинаем с одного файла по пути <code>scripts/npc/npc_abilities_custom.txt</code> со следующим содержимым:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;DOTAAbilities&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Ability1&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;SomeProperty1&quot;    &quot;1&quot;</span></span>
<span class="line"><span>        &quot;SomeProperty2&quot;    &quot;2&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Ability2&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;SomeProperty1&quot;    &quot;1&quot;</span></span>
<span class="line"><span>        &quot;SomeProperty2&quot;    &quot;2&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>Теперь предположим, что мы хотим разделить это на два файла и создать еще один файл <code>scripts/npc/abilities_2.txt</code>. У этого файла должен быть корневой элемент, как и у других файлов, мы можем просто скопировать <code>DOTAAbilities</code>. Также скопируйте содержимое, которое нужно разделить, и вот результат:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;DOTAAbilities&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Ability2&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;SomeProperty1&quot;    &quot;1&quot;</span></span>
<span class="line"><span>        &quot;SomeProperty2&quot;    &quot;2&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Теперь отредактируйте основной файл, включив в него новый файл <code>abilities_2.txt</code>, добавив <code>#base &quot;[relativePath]&quot;</code>. Результат:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#base &quot;abilities_2.txt&quot;</span></span>
<span class="line"><span>&quot;DOTAAbilities&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Ability1&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;SomeProperty1&quot;    &quot;1&quot;</span></span>
<span class="line"><span>        &quot;SomeProperty2&quot;    &quot;2&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>При загрузке этого файла KV движок теперь автоматически добавит содержимое <code>abilities_2.txt</code> в <code>npc_abilities_custom.txt</code>, объединив два корневых объекта в обоих файлах. Это означает, что имя корневого объекта не имеет значения, поэтому вместо <code>&quot;DOTAAbilities&quot;</code> у вас может быть <code>&quot;MYOTHERFILE&quot;</code> или даже просто пустая строка <code>&quot;&quot;</code>. У вас не должно быть одинаковых ключей в обоих корневых объектах, но если вы это сделаете, то те, которые определены позже (подумайте о том, что <code>#base</code> происходит до остальной части файла), переопределят уже определенные.</p><p>Это также поддерживает каталоги. Имейте в виду, что все пути относительны. Допустим, я создаю <code>scripts/npc/customAbilities/ability1.txt</code> и могу включить его из <code>scripts/npc/npc_abilities_custom.txt</code>, используя <code>#base &quot;customAbilities/ability1.txt&quot;</code>.</p><p><strong>PS:</strong> Другие расширения также разрешены. Вы можете назвать включенные файлы <code>.kv</code>.</p><h2 id="спасибо-за-указание-на-то-что-это-часть-спецификации-kv" tabindex="-1">Спасибо за указание на то, что это часть спецификации KV: <a class="header-anchor" href="#спасибо-за-указание-на-то-что-это-часть-спецификации-kv" aria-label="Permalink to &quot;Спасибо за указание на то, что это часть спецификации KV:&quot;">​</a></h2><ul><li>XMPPвоки</li><li>xPaw</li><li>Сетевой кожух</li></ul>`,18)])])}const m=n(i,[["render",t]]);export{d as __pageData,m as default};
